// HasActorMember filters parents that have a matching ActorMember using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to Members).
func (w householdEventWhereR[Q]) HasActorMember(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(Members.NameExpr()),
		sm.Where(Members.Columns.ID.EQ(w.cols.ActorID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

