// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to Households).
func (w householdEventWhereR[Q]) HasHousehold(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(Households.NameExpr()),
		sm.Where(Households.Columns.ID.EQ(w.cols.HouseholdID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

func (o *HouseholdEvent) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "ActorMember":
		rel, ok := retrieved.(*Member)
		if !ok {
			return fmt.Errorf("householdEvent cannot load %T as %q", retrieved, name)
		}

		o.R.ActorMember = rel
		o.R.Loaded.ActorMember = true

		if rel != nil {
			rel.R.ActorHouseholdEvents = HouseholdEventSlice{o}
		}
		return nil
	case "Household":
		rel, ok := retrieved.(*Household)
		if !ok {
			return fmt.Errorf("householdEvent cannot load %T as %q", retrieved, name)
		}

		o.R.Household = rel
		o.R.Loaded.Household = true

		if rel != nil {
			rel.R.HouseholdEvents = HouseholdEventSlice{o}
		}
		return nil
	default:
		return fmt.Errorf("householdEvent has no relationship %q", name)
	}
}

