// LoadActorMember loads the householdEvent's ActorMember into the .R struct
func (o *HouseholdEvent) LoadActorMember(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.ActorMember = nil
	o.R.Loaded.ActorMember = false

	related, err := o.ActorMember(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.ActorHouseholdEvents = HouseholdEventSlice{o}

	o.R.ActorMember = related
	o.R.Loaded.ActorMember = true
	return nil
}

// LoadActorMember loads the householdEvent's ActorMember into the .R struct
func (os HouseholdEventSlice) LoadActorMember(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	members, err := os.ActorMember(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.ActorMember = nil
		o.R.Loaded.ActorMember = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	householdEventByKey := make(map[uuid.UUID][]*HouseholdEvent, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		// NULL never matches any row in SQL, so don't add it to the map
		if !o.ActorID.Valid {
			continue
		}

		householdEventByKey[o.ActorID.V] = append(householdEventByKey[o.ActorID.V], o)
	}

	for _, rel := range members {

		owners, ok := householdEventByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.ActorMember != nil {
				continue
			}

			rel.R.ActorHouseholdEvents = append(rel.R.ActorHouseholdEvents, o)

			o.R.ActorMember = rel

		}
	}

	return nil
}

